"""Regress the validators against notes generated by all four real templates."""

from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
import unittest

from template_support import (
    ROOT, TEMPLATE_TYPES, document_body, render_template, render_template_result,
    replace_table, table_data, v2_body, workbook_body,
)


SPEC = importlib.util.spec_from_file_location(
    "template_note_validator", ROOT.joinpath("literature-zotero2obsidian", "scripts", "validate_note.py")
)
assert SPEC and SPEC.loader
validator = importlib.util.module_from_spec(SPEC)
sys.modules[SPEC.name] = validator
SPEC.loader.exec_module(validator)


class TemplateCompatibilityTests(unittest.TestCase):
    def generated(self, name: str, version: int) -> str:
        body = v2_body() if version == 2 else workbook_body(name)
        return render_template(name, body)

    def test_all_templates_generate_wrapped_v2_that_passes(self):
        for name in TEMPLATE_TYPES:
            with self.subTest(template=name):
                note = self.generated(name, 2)
                self.assertIn("```rich-table\n---\n", note)
                self.assertIn("\n---\n```\n^tbl-1\n", note)
                data = table_data(note)
                self.assertEqual(data["version"], 2)
                self.assertIs(data["locked"], True)
                self.assertEqual(data["theme"], "grid")
                self.assertEqual(validator.validate_note(note), [])

    def test_all_templates_generate_wrapped_v3_with_each_sheet_normalized(self):
        for name in TEMPLATE_TYPES:
            with self.subTest(template=name):
                note = self.generated(name, 3)
                self.assertIn("```rich-table\n---\n", note)
                self.assertIn("\n---\n```\n^tbl-1\n", note)
                data = table_data(note)
                self.assertEqual(data["version"], 3)
                self.assertEqual(len(data["sheets"]), 2)
                for sheet in data["sheets"]:
                    self.assertIs(sheet["locked"], True)
                    self.assertEqual(sheet["theme"], "grid")
                self.assertEqual(validator.validate_note(note), [])

    def test_unwrapped_variants_of_generated_v2_and_v3_remain_valid(self):
        for name in TEMPLATE_TYPES:
            for version in (2, 3):
                with self.subTest(template=name, version=version):
                    note = self.generated(name, version)
                    unwrapped = replace_table(note, table_data(note), wrapped=False)
                    self.assertEqual(validator.validate_note(unwrapped), [])

    def test_every_sheet_lock_and_theme_are_checked_independently(self):
        for name in TEMPLATE_TYPES:
            note = self.generated(name, 3)
            for index in (0, 1):
                for field, bad_value, code in (
                    ("locked", False, "TABLE_UNLOCKED"),
                    ("theme", "minimal", "TABLE_THEME"),
                ):
                    with self.subTest(template=name, sheet=index + 1, field=field):
                        data = table_data(note)
                        # An outer workbook flag cannot stand in for sheet flags.
                        data.update({"locked": True, "theme": "grid"})
                        data["sheets"][index][field] = bad_value
                        findings = validator.validate_note(replace_table(note, data))
                        matches = [finding for finding in findings if finding.code == code]
                        self.assertEqual(len(matches), 1, findings)
                        self.assertIn(f"工作表 {index + 1}", matches[0].message)

    def test_second_sheet_visible_fields_are_scanned_for_broken_links(self):
        for name in TEMPLATE_TYPES:
            note = self.generated(name, 3)
            for field in ("title", "footer", "column", "cell"):
                with self.subTest(template=name, field=field):
                    data = table_data(note)
                    sheet = data["sheets"][1]
                    broken = "[来源](<#^missing-second-sheet>)"
                    if field == "column":
                        sheet["columns"][0]["name"] = broken
                    elif field == "cell":
                        first_column = sheet["columns"][0]["id"]
                        sheet["rows"][0]["cells"][first_column] = broken
                    else:
                        sheet[field] = broken
                    findings = validator.validate_note(replace_table(note, data))
                    matches = [finding for finding in findings if finding.code == "MISSING_ANCHOR"]
                    self.assertEqual(len(matches), 1, findings)
                    self.assertIn("missing-second-sheet", matches[0].message)
                    self.assertIn("工作表 2", matches[0].message)

    def test_template_generated_v2_cell_broken_link_is_detected(self):
        for name in TEMPLATE_TYPES:
            with self.subTest(template=name):
                note = self.generated(name, 2)
                data = table_data(note)
                column = data["columns"][1]["id"]
                data["rows"][0]["cells"][column] = "[[#^missing-v2|来源]]"
                findings = validator.validate_note(replace_table(note, data))
                self.assertEqual([finding.code for finding in findings], ["MISSING_ANCHOR"])
                self.assertIn("missing-v2", findings[0].message)

    def test_harness_uses_in_memory_app_and_api_and_preserves_template(self):
        for name in TEMPLATE_TYPES:
            with self.subTest(template=name):
                path = ROOT.joinpath("template", name)
                before = path.read_bytes()
                result = render_template_result(name, v2_body())
                self.assertEqual(result["events"]["prompts"], 3)
                self.assertEqual(result["events"]["requests"], [{
                    "hostname": "127.0.0.1", "port": 23119, "path": "/api/users/0/items/TEST0001",
                }])
                self.assertEqual(len(result["events"]["renames"]), 1)
                self.assertEqual(path.read_bytes(), before)

    def test_figure_table_copies_preserve_source_fields_and_existing_anchors(self):
        for name in TEMPLATE_TYPES:
            for version in (2, 3):
                with self.subTest(template=name, version=version):
                    data = table_data(self.generated(name, version))
                    sheets = data["sheets"] if version == 3 else [data]
                    for sheet in sheets:
                        sheet["title"] = "**图9内表格：** 来源中的分类表"
                        sheet["columns"][0]["name"] = "图内文字"
                        column = sheet["columns"][0]["id"]
                        sheet["rows"][0]["cells"][column] = "图内文字：原表中的字段"
                        sheet["footer"] = "保留原图。[1](<#^ref-1>)"
                    block = "```rich-table\n" + json.dumps(data, ensure_ascii=False) + "\n```"
                    body = document_body(block).replace(
                        "表内引用可回溯到本文书目。",
                        "图内文字用于标识数据类别，表格副本按来源转录。\n\n"
                        "![[assets/figure.png]]  \n**图9：** 原始图件。\n^fig-9",
                    ).replace("\n^tbl-1\n", "\n^tbl-fig-main-9\n")
                    note = render_template(name, body)
                    actual = table_data(note)
                    self.assertEqual(actual, data)
                    self.assertIn("图内文字用于标识数据类别", note)
                    self.assertIn("![[assets/figure.png]]  \n**图9：** 原始图件。\n^fig-9", note)
                    self.assertEqual(note.count("\n^tbl-fig-main-9\n"), 1)
                    self.assertIn("[1](<#^ref-1>)", note)
                    self.assertEqual(validator.validate_note(note), [])

    def test_real_templates_preserve_id_based_merges_in_v2_and_every_v3_sheet(self):
        for name in TEMPLATE_TYPES:
            for version in (2, 3):
                with self.subTest(template=name, version=version):
                    data = table_data(self.generated(name, version))
                    sheets = data["sheets"] if version == 3 else [data]
                    for sheet in sheets:
                        column, value_column = (item["id"] for item in sheet["columns"])
                        first = sheet["rows"][0]
                        first["cells"][column] = "组甲"
                        sheet["rows"].append({
                            "id": "r_000002",
                            "cells": {column: "", value_column: "[1](<#^ref-1>)"},
                        })
                        sheet["merges"] = [{
                            "anchor": first["id"] + "." + column,
                            "end": "r_000002." + column,
                        }]
                    block = "```rich-table\n" + json.dumps(data, ensure_ascii=False) + "\n```"
                    note = render_template(name, document_body(block))
                    actual = table_data(note)
                    self.assertEqual(actual, data)
                    actual_sheets = actual["sheets"] if version == 3 else [actual]
                    for sheet in actual_sheets:
                        self.assertEqual(len(sheet["rows"]), 2)
                        self.assertEqual(len(sheet["merges"]), 1)
                        self.assertIs(sheet["locked"], True)
                        self.assertEqual(sheet["theme"], "grid")
                    self.assertEqual(note.count("\n^tbl-1\n"), 1)
                    self.assertEqual(validator.validate_note(note), [])

    def test_transcription_words_inside_fences_are_preserved_as_data(self):
        for name in TEMPLATE_TYPES:
            for fence in ("```", "~~~"):
                with self.subTest(template=name, fence=fence):
                    literal = fence + "text\n图内文字：原始代码输入\n" + fence
                    body = v2_body().replace(
                        "表内引用可回溯到本文书目。",
                        "图内文字是本段讨论的对象。\n\n" + literal,
                    )
                    note = render_template(name, body)
                    self.assertIn(literal, note)
                    self.assertIn("图内文字是本段讨论的对象。", note)
                    self.assertEqual(validator.validate_note(note), [])

    def test_extra_transcription_labels_are_still_rejected_by_real_templates(self):
        labels = (
            "图内文字：额外转录",
            "**图内标注：** 额外说明",
            "- 图内节点依次为：甲、乙",
            "### 1.1 图内文字翻译",
            "图内翻译：额外翻译",
        )
        for name in TEMPLATE_TYPES:
            for label in labels:
                with self.subTest(template=name, label=label):
                    body = v2_body().replace("表内引用可回溯到本文书目。", label)
                    with self.assertRaises(subprocess.CalledProcessError) as raised:
                        render_template(name, body)
                    self.assertIn("额外的图内转录或解释标记", raised.exception.stderr)


if __name__ == "__main__":
    unittest.main()
